package com.example.yiyan;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.util.*;
public class QuoteWidgetProvider extends AppWidgetProvider {
 public static final String ACTION="com.example.yiyan.NEXT_QUOTE";
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids) update(c,m,id);}
 public void onReceive(Context c,Intent i){super.onReceive(c,i);if(ACTION.equals(i.getAction())||Intent.ACTION_USER_PRESENT.equals(i.getAction())){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,QuoteWidgetProvider.class));for(int id:ids)update(c,m,id);}}
 private void update(Context c,AppWidgetManager m,int id){android.content.SharedPreferences p=c.getSharedPreferences("settings",0);ArrayList<Quote> a=new ArrayList<>();String edited=p.getString("editable_library","");if(!edited.isEmpty()){for(String z:edited.split("\\n")){String[] x=z.split("\\|",-1);if(x.length>=3&&!x[0].trim().isEmpty())a.add(new Quote(x[0].trim(),x[1].trim(),x[2].trim(),"用户编辑"));}}else for(Quote q:QuoteLibrary.ALL)if(q.kind.equals("译写 / 意译"))a.add(q);for(String z:p.getStringSet("custom_quotes",new java.util.HashSet<String>())){String[] x=z.split("\\|",-1);if(x.length>=3)a.add(new Quote(x[0],x[1],x[2],"用户添加"));}if(a.isEmpty())return;int n=(p.getInt("quoteIndex",-1)+1)%a.size();p.edit().putInt("quoteIndex",n).putString("lastLog","已切换："+a.get(n).text+"（"+System.currentTimeMillis()+"）").apply();android.util.Log.i("99YIYAN_LOG","切换到第"+n+"条："+a.get(n).text);Quote q=a.get(n);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_quote);v.setTextViewText(R.id.quote_text,q.text);v.setTextViewText(R.id.quote_meta,"— "+zhAuthor(q.author)+" · 《"+zhWork(q.work)+"》 · "+q.kind);v.setTextViewTextSize(R.id.quote_text,android.util.TypedValue.COMPLEX_UNIT_SP,p.getInt("fontSize",16));boolean night=(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;int color=p.getInt("themeColor",0xff6750a4);if(p.getBoolean("monet",false)&&android.os.Build.VERSION.SDK_INT>=31)color=c.getColor(android.R.color.system_accent1_600);if(night)color=0xffd0bcff;v.setTextColor(R.id.quote_text,night?0xfff4eff7:0xff24212a);v.setTextColor(R.id.quote_meta,color);v.setInt(R.id.widget_root,"setBackgroundColor",night?0xff211f24:p.getInt("backgroundColor",0xfffff9f0));Intent x=new Intent(ACTION);x.setPackage(c.getPackageName());v.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getBroadcast(c,id,x,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}
 private String zhAuthor(String s){String[][] m={{"Socrates","苏格拉底"},{"Plato","柏拉图"},{"Aristotle","亚里士多德"},{"Nietzsche","尼采"},{"Descartes","笛卡尔"},{"Kant","康德"},{"Rousseau","卢梭"},{"Camus","加缪"},{"Sartre","萨特"},{"Laozi","老子"},{"Confucius","孔子"},{"Marcus Aurelius","马可·奥勒留"},{"Epictetus","爱比克泰德"},{"Wittgenstein","维特根斯坦"},{"Hannah Arendt","汉娜·阿伦特"},{"Heidegger","海德格尔"},{"Foucault","福柯"},{"Rawls","罗尔斯"}};for(String[] x:m)if(s.equals(x[0]))return x[1];return s;}
 private String zhWork(String s){String[][] m={{"Republic","理想国"},{"Apology","申辩篇"},{"Nicomachean Ethics","尼各马可伦理学"},{"The Social Contract","社会契约论"},{"Meditations","沉思录"},{"Tao Te Ching","道德经"},{"The Myth of Sisyphus","西西弗斯神话"},{"Being and Nothingness","存在与虚无"},{"Tractatus Logico-Philosophicus","逻辑哲学论"},{"Philosophical Investigations","哲学研究"},{"On Liberty","论自由"},{"Utilitarianism","功利主义"},{"Groundwork of the Metaphysics of Morals","道德形而上学奠基"},{"What Is Enlightenment?","什么是启蒙？"},{"The Second Sex","第二性"},{"The Human Condition","人的境况"},{"Discipline and Punish","规训与惩罚"},{"A Theory of Justice","正义论"}};for(String[] x:m)if(s.equals(x[0]))return x[1];return s;}
}
